from collections import Counter

def _runs(indices):
    if not indices:
        return []
    out=[]; start=prev=indices[0]
    for x in indices[1:]:
        if x != prev+1:
            out.append((start,prev)); start=x
        prev=x
    out.append((start,prev))
    return out

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    counts=Counter(v for row in a for v in row)
    bg=counts.most_common(1)[0][0]
    colors=[c for c in counts if c!=bg]
    # A boundary color forms paired runs on opposite sides of the grid.
    candidates=[]
    for c in colors:
        left=_runs([r for r in range(h) if a[r][0]==c])
        right=_runs([r for r in range(h) if a[r][w-1]==c])
        top=_runs([x for x in range(w) if a[0][x]==c])
        bottom=_runs([x for x in range(w) if a[h-1][x]==c])
        if left and right and max(y-x+1 for x,y in left)>=2 and max(y-x+1 for x,y in right)>=2:
            candidates.append((c,'v',left,right))
        if top and bottom and max(y-x+1 for x,y in top)>=2 and max(y-x+1 for x,y in bottom)>=2:
            candidates.append((c,'h',top,bottom))
    if not candidates:
        return a
    marker,orient,first,second=max(candidates,key=lambda z: sum(counts[z[0]] for _ in [0]))
    signals=[c for c in colors if c!=marker]
    if not signals:
        return a
    sig=max(signals,key=lambda c: counts[c])
    if orient=='v':
        left,right=first,second
        # Pick the marker stripe that contains the signal pattern as its source.
        def contained_count(bands):
            return max((sum(1 for r in range(lo,hi+1) for x in range(w) if a[r][x]==sig) for lo,hi in bands),default=0)
        nl,nr=contained_count(left),contained_count(right)
        if max(nl,nr)==0:
            return a
        if nl>=nr:
            source, dest, source_side, dest_side=left,right,'left','right'
        else:
            source, dest, source_side, dest_side=right,left,'right','left'
        slo,shi=max(source,key=lambda b:sum(1 for r in range(b[0],b[1]+1) for x in range(w) if a[r][x]==sig))
        dlo,dhi=min(dest,key=lambda b:abs((b[1]-b[0])-(shi-slo)))
        # Each signal cell extends toward its boundary marker; the endpoint is marked 4.
        signal_positions=[(r,x) for r in range(slo,shi+1) for x in range(w) if grid[r][x]==sig]
        for r,x in signal_positions:
            a[r][x]=4
            if source_side=='left':
                for xx in range(1,x):
                    if a[r][xx]==bg: a[r][xx]=sig
            else:
                for xx in range(x+1,w-1):
                    if a[r][xx]==bg: a[r][xx]=sig
        # Copy the active row pattern to the opposite stripe and fill inward.
        active=[r for r in range(slo,shi+1) if any(grid[r][x]==sig for x in range(w))]
        for r in active:
            rr=dlo+(r-slo)
            if rr<dlo or rr>dhi: continue
            if dest_side=='left':
                for x in range(1,w):
                    if a[rr][x]==bg: a[rr][x]=sig
            else:
                for x in range(0,w-1):
                    if a[rr][x]==bg: a[rr][x]=sig
        return a
    # Horizontal boundary stripes: emit a ray along the inward perpendicular
    # direction from the rightmost cell of each stripe.
    top,bottom=first,second
    for side,bands in [('top',top),('bottom',bottom)]:
        for lo,hi in bands:
            col=lo
            if side=='top':
                rr=1
                while rr<h:
                    v=a[rr][col]
                    if v!=bg:
                        if v==sig: a[rr][col]=4
                        break
                    a[rr][col]=sig; rr+=1
            else:
                rr=h-2
                while rr>=0:
                    v=a[rr][col]
                    if v!=bg:
                        if v==sig: a[rr][col]=4
                        break
                    a[rr][col]=sig; rr-=1
    return a

